'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var powf = require( '@stdlib/math/base/special/powf' );
var expf = require( '@stdlib/math/base/special/expf' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var absf = require( '@stdlib/math/base/special/absf' );
var cospif = require( '@stdlib/math/base/special/cospif' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PHI = require( '@stdlib/constants/float32/phi' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var NAN = require( '@stdlib/constants/float32/nan' );


// VARIABLES //

var SQRT_5 = f32( 2.23606797749979 ); // √5
var LN_PHI = f32( 0.48121182505960347 ); // ln(φ)
var LN_SQRT_5 = f32( 0.80471895621705014 ); // ln(√5)
var OVERFLOW_THRESHOLD = f32( 184.37377929687500 ); // first (single-precision) value `x` for which `φ^x` overflows


// MAIN //

/**
* Evaluates Binet's formula extended to real numbers.
*
* ## Method
*
* Binet's formula is
*
* ```tex
* \operatorname{binet}(x) = \frac{\varphi^x - \cos(\pi x)\,\varphi^{-x}}{\sqrt{5}}
* ```
*
* In single-precision floating-point arithmetic, directly evaluating \\( \varphi^x \\) overflows once \\( x \\) exceeds the natural logarithm of the maximum single-precision floating-point number divided by \\( \ln(\varphi) \\), even though the function value \\( \varphi^x / \sqrt{5} \\) remains representable for \\( x < \bigl(\ln(\mathtt{FLT\_MAX}) + \tfrac{1}{2}\ln(5)\bigr) / \ln(\varphi) \\). We therefore factor out the dominant term. For \\( x \ge 0 \\),
*
* ```tex
* \operatorname{binet}(x) = \frac{\varphi^{|x|}}{\sqrt{5}} - \cos(\pi x)\,\frac{\varphi^{-|x|}}{\sqrt{5}}
* ```
*
* and for \\( x < 0 \\),
*
* ```tex
* \operatorname{binet}(x) = \frac{\varphi^{-|x|}}{\sqrt{5}} - \cos(\pi x)\,\frac{\varphi^{|x|}}{\sqrt{5}}.
* ```
*
* When the dominant term would overflow, it is evaluated in log space. For negative \\( x \\), the magnitude of the dominant term is \\( |\cos(\pi x)| \cdot \varphi^{|x|} / \sqrt{5} \\), so we fold \\( \ln|\cos(\pi x)| \\) into the exponent in order to preserve finiteness of results which are representable in single precision:
*
* ```tex
* \frac{|\cos(\pi x)| \cdot \varphi^{|x|}}{\sqrt{5}} = \exp\Bigl( |x|\,\ln(\varphi) + \ln|\cos(\pi x)| - \tfrac{1}{2}\ln(5) \Bigr).
* ```
*
* Note that the cancellation of the two terms of Binet's formula near \\( x = 0 \\) (and, for negative \\( x \\), near the negative half-integers) is inherent to the formula itself and limits _relative_ accuracy; _absolute_ accuracy is unaffected.
*
* @param {number} x - input value
* @returns {number} real-valued result
*
* @example
* var y = binetf( 0.0 );
* // returns 0.0
*
* @example
* var y = binetf( 1.0 );
* // returns 1.0
*
* @example
* var y = binetf( 2.0 );
* // returns ~1.0
*
* @example
* var y = binetf( 3.0 );
* // returns 2.0
*
* @example
* var y = binetf( 4.0 );
* // returns 3.0
*
* @example
* var y = binetf( 5.0 );
* // returns ~5.0
*
* @example
* var y = binetf( -1.0 );
* // returns 1.0
*
* @example
* var y = binetf( NaN );
* // returns NaN
*/
function binetf( x ) {
	var eps;
	var dom;
	var ax;
	var a;
	var b;
	var c;

	x = f32( x ); // ensure type consistency (values may arrive as `float64`s)
	if ( isnanf( x ) || x === PINF || x === NINF ) {
		return NAN;
	}
	ax = absf( x );
	if ( ax < OVERFLOW_THRESHOLD ) {
		a = powf( PHI, x );
		b = f32( cospif( x ) / a );
		return f32( f32( a - b ) / SQRT_5 );
	}
	// The input value is large enough that `powf( PHI, x )` (or `cospi(x)/powf(PHI,x)`) would overflow: evaluate the dominant term in log space
	eps = expf( f32( f32( -ax*LN_PHI ) - LN_SQRT_5 ) ); // φ^(-|x|)/√5
	if ( x > 0 ) {
		// The dominant term is φ^x/√5; the second term of Binet's formula is below single-precision resolution
		return expf( f32( f32( ax*LN_PHI ) - LN_SQRT_5 ) );
	}
	// The dominant term is -cos(πx)·φ^(-x)/√5; fold ln|cos(πx)| into the exponent to preserve finiteness (note: `lnf(0.0)` is `-infinity`, so exact half-integers naturally return `eps`)
	c = cospif( x );
	dom = expf( f32( f32( f32( ax*LN_PHI ) + lnf( absf( c ) ) ) - LN_SQRT_5 ) );
	return ( c > 0 ) ? f32( eps - dom ) : f32( eps + dom );
}


// EXPORTS //

module.exports = binetf;
